"""HM R6 B1 / RK 10:26 (contract): Fly reads the REAL reporter output (fixtures/live_report_contract.json, generated by
apps/api/src/trading-agents/live-report-contract.spec.ts from buildLiveCopyReports + the shared exit-fill helper and
pinned there by a deep-equal). It goes through live_copy_monitor.build_chains -> live_tile_gate -> live_guardian.

* The close time is close.fill_at_ts (Bitfinex's last exit fill mts), never 'now', never a report time.
* A loss rolls out of the rolling-24h cap after 24 h and out of the UTC-day cap on the next UTC day.
* No real fill time (or no real fill) => unreadable: entry block and non-countable, at any 'now'.
* Field audit: every field the monitor reads from a report is one the reporter actually sends."""
import json
from pathlib import Path

import pytest

import live_copy_monitor as lcm
import live_exit_fill as lef
import live_guardian as g
import live_tile_gate as ltg

FIX = json.loads((Path(__file__).parent / "fixtures" / "live_report_contract.json").read_text())
MIR = {"ok": True, "positions": [], "open_orders": [], "orphans": [], "balance": {"derivatives_available_usd": 206.79}}


def _chains(*keys):
    reports = [r for k in keys for r in FIX[k]]
    return lcm.build_chains([], reports)["accounts"]


def _close(key, i=-1):
    return [r for r in FIX[key] if r["type"] == "POSITION_CLOSED"][i]["close"]


def test_close_time_is_the_bitfinex_fill_time_from_close_fill_at_ts():
    ch = _chains("loss")[("gs1-loss", "A")]
    fill_ts = _close("loss")["fill_at_ts"]
    assert fill_ts == pytest.approx(FIX["t0_ms"] / 1000 + 600 - 0.4)
    assert ch["exit_fill_at_ts"] == fill_ts and ch["closed_at_ts"] == fill_ts and ch["exit_at_ts"] == fill_ts
    assert lef.exit_fill_ts(ch) == fill_ts
    assert ltg.trade_realised_pnl_usd(ch) == pytest.approx((99_690 - 100_000) * 0.002)
    assert lef.exit_fill_non_countable_reason(ch) is None


def test_loss_rolls_out_of_the_rolling_24h_and_daily_caps():
    chains = list(_chains("loss", "cleared").values())
    fill_ts = _close("loss")["fill_at_ts"]
    loss = (100_000 - 99_690) * 0.002 + (100_000 - _close("cleared")["price"]) * 0.002
    # one hour later: both losses are in the guardian's rolling ledger and the UTC-day cap
    st = {}
    g.evaluate(chains, MIR, st, fill_ts + 3600)
    assert st["ledger_loss_usd"] == pytest.approx(loss, abs=1e-4)
    _, total, n = ltg.daily_realised_loss(chains, fill_ts + 3600)
    assert n == 2 and total == pytest.approx(loss)
    # just past 24 h after the later fill: rolled out of the rolling window, and it is the next UTC day
    later = _close("cleared")["fill_at_ts"] + 24 * 3600 + 1
    st = {}
    v = g.evaluate(chains, MIR, st, later)
    assert st["ledger_loss_usd"] == 0
    assert ltg.VIOL_PNL_UNREADABLE not in {x["code"] for x in v}
    assert ltg.daily_realised_loss(chains, later)[2] == 0


def test_unreadable_close_blocks_at_any_now_and_is_non_countable():
    ch = _chains("unreadable")[("gs1-unread", "A")]
    assert ch["closed"] and ch["exit_fill_price"] is None and ch["closed_at_ts"] is None
    assert lef.exit_fill_non_countable_reason(ch) == "EXIT_FILL_UNREADABLE:none"
    for dt in (60, 3 * 86_400):
        now = FIX["t0_ms"] / 1000 + 800 + dt
        assert ltg.VIOL_PNL_UNREADABLE in {x["code"] for x in g.evaluate([ch], MIR, {}, now)}
        assert ltg.unreadable_pnl_rows([ch], now) == [ch]


def test_real_price_without_fill_time_is_unreadable_never_now():
    reports = json.loads(json.dumps(FIX["loss"]))
    for r in reports:
        if r["type"] == "POSITION_CLOSED":
            r["close"]["fill_at_ts"] = None
    ch = lcm.build_chains([], reports)["accounts"][("gs1-loss", "A")]
    assert lef.exit_fill_ts(ch) is None and g.close_ts(ch, 1e12) is None
    assert ltg.trade_realised_pnl_usd(ch) is None
    assert lef.exit_fill_non_countable_reason(ch) == "EXIT_FILL_UNREADABLE:no_fill_ts"
    assert ltg.VIOL_PNL_UNREADABLE in {x["code"] for x in g.evaluate([ch], MIR, {}, 1e12)}


def test_clearing_re_stamp_wins_with_its_own_fill_time():
    ch = _chains("cleared")[("gs1-cleared", "A")]
    assert ch["exit_fill_at_ts"] == _close("cleared")["fill_at_ts"]
    assert ch["exit_price_source"] == "stop_fill"
    assert lef.exit_fill_non_countable_reason(ch) is None


# Field audit: what build_chains reads per report type vs what the reporter sends (the fixture).
_READS = {
    "ORDER_PLACED": {"order": ["qty", "price", "type", "tif", "side", "entry_order_mode"]},
    "ORDER_FILLED": {"fill": ["price", "qty", "source"]},
    "STOP_CONFIRMED": {"stop": ["price", "exchange_order_id", "verified_on_exchange"]},
    "POSITION_CLOSED": {"close": ["price", "price_source", "fill_at_ts", "reason", "exit_order_class"]},
}
_TIMELINE = ["order_sent_at_ts", "exchange_ack_at_ts", "fill_at_ts", "stop_placed_at_ts", "stop_confirmed_at_ts",
             "exit_ack_at_ts", "exit_confirmed_at_ts", "exit_trigger_print_at_ts", "exit_fill_record_at_ts"]
# read by the monitor but never sent by the reporter: each must be harmless (display / audit only, never a gate input)
_NOT_SENT_OK = {"close.ts", "closed_at_ts", "timeline.closed_at_ts", "pnl_usd", "funding_usd", "exit_price", "exit_reason"}


def test_every_field_the_monitor_reads_is_sent_by_the_reporter():
    reports = [r for k in ("loss", "cleared", "unreadable") for r in FIX[k]]
    for typ, groups in _READS.items():
        rs = [r for r in reports if r["type"] == typ]
        assert rs, typ
        for grp, keys in groups.items():
            for k in keys:
                assert all(k in r[grp] for r in rs), f"{typ}.{grp}.{k} not sent by the reporter"
    for k in _TIMELINE:
        assert all(k in r["timeline"] or k.startswith("exit_") for r in reports), k
    closes = [r for r in reports if r["type"] == "POSITION_CLOSED"]
    assert all(k in r["timeline"] for r in closes for k in _TIMELINE if k.startswith("exit_"))
    # the not-sent set is really not sent, and none of it feeds D3 (trade_realised_pnl_usd / exit_fill_ts)
    for r in closes:
        assert "ts" not in r["close"] and "closed_at_ts" not in r and "pnl_usd" not in r and "funding_usd" not in r
    src = Path(ltg.__file__).read_text()
    body = src[src.index("def trade_realised_pnl_usd"):src.index("def daily_realised_loss")]
    assert "pnl_usd\")" not in body and "funding" not in body.split('"""')[-1]
